30	import org.springframework.transaction.annotation.Transactional;
31	
32	/**
33	 * Keeps the people's claims on a sheet. A new claim with no date is dated the sheet's entry date while it is set, else
34	 * the sheet's today; an edited one with no date the sheet's today. A claim belongs to the period its due-by (fixed when
35	 * it is added) falls in; one whose due-by is in a closed period cannot be added, edited, deferred or change status. Only a DRAFT claim can be edited; a PENDING claim, waiting for a
36	 * steward to approve or reject it, is otherwise handled like an OPEN one. No claim
37	 * can be dated after the retirement date of its person. A claim whose due is above the proof threshold on its date
38	 * cannot be settled or approved without a proof; one whose due is above the note threshold on its date cannot be
39	 * opened with an empty note. A claim with a negative amount is a correction: it must name,
40	 * by number, a SETTLED claim of the same person that it corrects, and its due has no floor and no late charge.
41	 */
42	@Service
43	public class ClaimService {
44	
45	    /** The days after its settlement within which a steward may still void a SETTLED claim. */
46	    private static final int SETTLED_VOID_DAYS = 7;
