147	    /**
148	     * Adds a claim with an external reference (blank: none), refused when the reference is already used on the sheet,
149	     * and comma separated tags (blank: none).
150	     */
151	    @Transactional
152	    public Claim add(String sheetId, String user, Long personId, BigDecimal amount, LocalDate date, String note,
153	            String corrects, String ref, String tagText) {
154	        RollupService.Snapshot before = rollup.snapshot(sheetId);
155	        Person person = people.findByIdAndSheetId(personId, sheetId)
156	                .orElseThrow(() -> new PersonNotFoundException(sheetId, personId));
157	        LocalDate dated = date != null ? date : sheets.entryDate(sheetId);
158	        // Due by its person's terms on its date in business days after it, skipping the sheet's holidays now, fixed from now on;
159	        // its period is the one of its due-by.
160	        int terms = termsFor(sheetId, person, dated);
161	        LocalDate dueBy = holidays.businessDaysAfter(sheetId, dated, terms);
162	        periods.requireOpen(sheetId, dueBy);
163	        person.requireClaimable(dated);
164	        LocalDate correctedDate = requireCorrection(sheetId, personId, amount, corrects);
165	        Claim claim = new Claim(sheetId, personId, amount, dated, noteOf(note));
166	        claim.setCorrects(corrects);
167	        claim.setRoundingDate(correctedDate != null ? correctedDate : dated);
168	        claim.setDueBy(dueBy);
169	        claim.setTerms(terms);
170	        // Taking the next list place locks the sheet, so two adds of the same reference do not both pass the check.
171	        claim.setListed(sheets.nextListed(sheetId));
172	        String reference = refOf(ref);
173	        if (reference != null && claims.existsBySheetIdAndRefIgnoreCase(sheetId, reference)) {
174	            throw new ClaimRefException(reference);
175	        }
176	        claim.setRef(reference);
177	        claim.setTags(tagged(sheetId, tagText));
178	        claim.setLateEntry(periods.softClosedOn(sheetId, dueBy));
179	        Claim saved = claims.saveAndFlush(claim);
180	        log(sheetId, user, person, saved);
181	        audit.recordOnCommit(record("CLAIM_ADDED", user, person, saved)
182	                + (saved.getRef() == null ? "" : " ref=" + saved.getRef())
183	                + (saved.getTags() == null ? "" : " tags=" + saved.getTags()));
184	        if (saved.isLateEntry()) {
185	            audit.recordOnCommit(record("LATE_ENTRY", user, person, saved));
186	        }
187	        rollup.recordChanges(sheetId, user, before);
188	        return saved;
189	    }
