191	    @Transactional
192	    public Claim update(String sheetId, String user, Long id, BigDecimal amount, LocalDate date, String note,
193	            String corrects, String ref, String tagText) {
194	        RollupService.Snapshot before = rollup.snapshot(sheetId);
195	        Claim claim = claims.findForUpdate(id, sheetId)
196	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
197	        // Only a DRAFT can be edited: an OPEN claim is changed by voiding it and adding a new one.
198	        if (claim.getStatus() != ClaimStatus.DRAFT) {
199	            throw new ClaimNotEditableException(id, claim.getStatus());
200	        }
201	        // Not while another user has its editor open.
202	        if (claim.isLockedAgainst(user)) {
203	            throw new ClaimLockedException(id, claim.getLockedBy());
204	        }
205	        LocalDate dated = dateOr(sheetId, date);
206	        // Its due-by, and so its period, stays as fixed when it was added.
207	        periods.requireOpen(sheetId, claim.getDueBy());
208	        people.findByIdAndSheetId(claim.getPersonId(), sheetId)
209	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()))
210	                .requireClaimable(dated);
211	        LocalDate correctedDate = requireCorrection(sheetId, claim.getPersonId(), amount, corrects);
212	        String reference = refOf(ref);
213	        if (reference != null && claims.existsBySheetIdAndRefIgnoreCaseAndIdNot(sheetId, reference, id)) {
214	            throw new ClaimRefException(reference);
215	        }
216	        claim.setRef(reference);
217	        claim.setTags(tagged(sheetId, tagText));
218	        claim.setAmount(amount);
219	        claim.setCorrects(corrects);
220	        claim.setDate(dated);
221	        claim.setRoundingDate(correctedDate != null ? correctedDate : dated);
222	        claim.setNote(noteOf(note));
223	        claim.setEditedBy(user);
224	        // Saving the editor releases its lock.
225	        claim.setLockedBy(null);
226	        Claim saved = claims.saveAndFlush(claim);
227	        Person person = people.findByIdAndSheetId(saved.getPersonId(), sheetId)
228	                .orElseThrow(() -> new PersonNotFoundException(sheetId, saved.getPersonId()));
229	        audit.recordOnCommit(record("CLAIM_EDITED", user, person, saved));
230	        rollup.recordChanges(sheetId, user, before);
231	        return saved;
232	    }
