234	    /**
235	     * Open the claim's editor for the user, locking the claim against other users' edits until it is saved or
236	     * cancelled, or the sheet's today changes. Refused, taking no lock, for a claim that cannot be edited: not a DRAFT,
237	     * due by a date in a closed period, or locked by another user. The user's own lock is taken again.
238	     */
239	    @Transactional
240	    public Claim lock(String sheetId, String user, Long id) {
241	        Claim claim = claims.findForUpdate(id, sheetId)
242	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
243	        if (claim.getStatus() != ClaimStatus.DRAFT) {
244	            throw new ClaimNotEditableException(id, claim.getStatus());
245	        }
246	        periods.requireOpen(sheetId, claim.getDueBy());
247	        if (claim.isLockedAgainst(user)) {
248	            throw new ClaimLockedException(id, claim.getLockedBy());
249	        }
250	        claim.setLockedBy(user);
251	        return claims.saveAndFlush(claim);
252	    }
