258	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
259	        if (user.equals(claim.getLockedBy())) {
260	            claim.setLockedBy(null);
261	            return claims.saveAndFlush(claim);
262	        }
263	        return claim;
