284	    /**
285	     * Settle a claim as part of a bulk settle, as {@link #changeStatus(String, String, Long, ClaimStatus)}: once it is
286	     * SETTLED or PENDING it carries the batch number the supplier gives, asked for only then, within the same change.
287	     */
288	    @Transactional
289	    public Claim settleInBatch(String sheetId, String user, Long id, LongSupplier batch) {
290	        return changeStatus(sheetId, user, id, ClaimStatus.SETTLED, null, batch);
291	    }
