293	    private Claim changeStatus(String sheetId, String user, Long id, ClaimStatus status, String voidReason,
294	            LongSupplier batch) {
295	        Claim claim = claims.findForUpdate(id, sheetId)
296	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
297	        boolean voidsSettled = status == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED;
298	        if (!voidsSettled && (!claim.getStatus().canMoveTo(status) || status == ClaimStatus.PENDING)) {
299	            throw new ClaimStatusException(id, claim.getStatus(), status);
300	        }
301	        // The sheet's permission matrix decides which roles may open, settle or void.
302	        String action = switch (status) {
303	            case OPEN -> "open";
304	            case SETTLED -> "settle";
305	            case VOID -> "void";
306	            case DRAFT, PENDING -> throw new ClaimStatusException(id, claim.getStatus(), status);
307	        };
308	        if (!roles.may(sheetId, user, action)) {
309	            throw new ClaimActionForbiddenException(id, user, action);
310	        }
311	        if (voidsSettled) {
312	            requireSettledVoidable(sheetId, user, claim);
313	        }
314	        periods.requireOpen(sheetId, claim.getDueBy());
315	        String reason = status == ClaimStatus.VOID ? requireVoidReason(sheetId, id, voidReason) : null;
316	        // A deferred claim cannot be settled until the sheet's today reaches the date it is deferred until.
317	        if (status == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) {
318	            throw new ClaimDeferException(id, "it is deferred until " + claim.getDeferredUntil());
319	        }
320	        // Four eyes: whoever opened or last edited a claim cannot also settle it.
321	        if (status == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
322	            throw new ClaimSettledByOpenerException(id, user, "opened");
323	        }
324	        if (status == ClaimStatus.SETTLED && user.equals(claim.getEditedBy())) {
325	            throw new ClaimSettledByOpenerException(id, user, "last edited");
326	        }
327	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
328	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
329	        if (status == ClaimStatus.SETTLED) {
330	            requireProof(sheetId, person, claim);
331	        }
332	        if (status == ClaimStatus.OPEN) {
333	            requireNote(sheetId, person, claim);
334	        }
335	        // A clerk settles only a claim whose due (the one its statement bound it to, else worked out from the rate)
336	        // is at or below the clerk limit; one above it goes to PENDING. A due of n/a is within any limit.
337	        if (status == ClaimStatus.SETTLED && roles.roleOf(sheetId, user) == Role.CLERK) {
338	            BigDecimal limit = settings.get(sheetId).getClerkLimit();
339	            BigDecimal due = liveDue(sheetId, person, claim, figureOf(sheetId, person, claim));
340	            if (limit != null && due != null && due.compareTo(limit) > 0) {
341	                status = ClaimStatus.PENDING;
342	            }
343	        }
344	        RollupService.Snapshot before = rollup.snapshot(sheetId);
345	        String due = status == ClaimStatus.SETTLED ? settle(sheetId, person, claim)
346	                : voidsSettled ? " reversed=" + shownDue(sheetId, person, claim) : "";
347	        claim.setStatus(status);
348	        if (status == ClaimStatus.VOID) {
349	            claim.setVoidReason(reason);
350	        }
351	        // Settled one at a time, a claim carries no batch; settled by a bulk settle, it carries that batch's number.
352	        if (status == ClaimStatus.SETTLED || status == ClaimStatus.PENDING) {
353	            claim.setSettleBatch(batch == null ? null : batch.getAsLong());
354	        }
355	        // A voided claim keeps its number (never reused), and the CLAIM_VOIDED record carries it.
356	        String number = claim.getNumber();
357	        if (status == ClaimStatus.OPEN) {
358	            number = nextNumber(sheetId, claim.getDueBy());
359	            claim.setNumber(number);
360	            claim.setOpenedBy(user);
361	        }
362	        Claim saved = claims.saveAndFlush(claim);
363	        log(sheetId, user, person, saved);
364	        String event = switch (status) {
365	            case OPEN -> "CLAIM_OPENED";
366	            case PENDING -> "CLAIM_PENDING";
367	            case SETTLED -> "CLAIM_SETTLED";
368	            case VOID -> "CLAIM_VOIDED";
369	            case DRAFT -> throw new IllegalStateException();
370	        };
371	        audit.recordOnCommit(record(event, user, person, saved) + numberOf(number) + due
372	                + (reason == null ? "" : " reason=" + reason));
373	        if (status == ClaimStatus.SETTLED) {
374	            watches.notifyWatchers(sheetId, user, person, number);
375	        }
376	        rollup.recordChanges(sheetId, user, before);
377	        return saved;
378	    }
