399	    /**
400	     * A steward other than its opener or last editor approves a PENDING claim: it becomes SETTLED, its due frozen at that moment from
401	     * its live figure.
402	     */
403	    @Transactional
404	    public Claim approve(String sheetId, String user, Long id) {
405	        Claim claim = pendingForDecision(sheetId, user, id, ClaimStatus.SETTLED);
406	        if (user.equals(claim.getOpenedBy())) {
407	            throw new ClaimApprovalForbiddenException(id, user, "whoever opened a claim cannot approve it");
408	        }
409	        if (user.equals(claim.getEditedBy())) {
410	            throw new ClaimApprovalForbiddenException(id, user, "whoever last edited a claim cannot approve it");
411	        }
412	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
413	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
414	        requireProof(sheetId, person, claim);
415	        RollupService.Snapshot before = rollup.snapshot(sheetId);
416	        String due = settle(sheetId, person, claim);
417	        claim.setStatus(ClaimStatus.SETTLED);
418	        Claim saved = claims.saveAndFlush(claim);
419	        log(sheetId, user, person, saved);
420	        audit.recordOnCommit(record("CLAIM_APPROVED", user, person, saved) + numberOf(saved.getNumber()) + due);
421	        watches.notifyWatchers(sheetId, user, person, saved.getNumber());
422	        rollup.recordChanges(sheetId, user, before);
423	        return saved;
424	    }
