426	    /**
427	     * A steward rejects a PENDING claim with a reason: it goes back to OPEN, bound again by its person's last statement
428	     * if that statement included it.
429	     */
430	    @Transactional
431	    public Claim reject(String sheetId, String user, Long id, String reason) {
432	        Claim claim = pendingForDecision(sheetId, user, id, ClaimStatus.OPEN);
433	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
434	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
435	        RollupService.Snapshot before = rollup.snapshot(sheetId);
436	        claim.setStatus(ClaimStatus.OPEN);
437	        // Back to OPEN, it is no longer settled by the batch that sent it to PENDING.
438	        claim.setSettleBatch(null);
439	        Claim saved = claims.saveAndFlush(claim);
440	        log(sheetId, user, person, saved);
441	        audit.recordOnCommit(record("CLAIM_REJECTED", user, person, saved) + numberOf(saved.getNumber())
442	                + " reason=" + reason);
443	        rollup.recordChanges(sheetId, user, before);
444	        return saved;
445	    }
