447	    /**
448	     * A user whose role may reassign moves a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its date and,
449	     * unless a draft, takes the next number in the sequence it is numbered in (its old one is never used again), loses any figure a statement bound it to (live again until its new person's next statement), and is listed as
450	     * its new person's newest claim. Refused for a SETTLED or VOID claim, its own person, a closed period, a new person
451	     * retired before its date, or a user whose role may not reassign.
452	     */
453	    @Transactional
454	    public Claim reassign(String sheetId, String user, Long id, Long toPersonId) {
455	        return reassign(sheetId, user, id, toPersonId, false);
456	    }
