458	    /**
459	     * Reassign as {@link #reassign(String, String, Long, Long)}; with {@code toOwnAllowed} (a bulk reassign) a claim
460	     * already the person's is moved too, listed again as its newest claim.
461	     */
462	    @Transactional
463	    public Claim reassign(String sheetId, String user, Long id, Long toPersonId, boolean toOwnAllowed) {
464	        Claim claim = claims.findForUpdate(id, sheetId)
465	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
466	        if (!roles.may(sheetId, user, "reassign")) {
467	            throw new ClaimReassignForbiddenException(id, user);
468	        }
469	        if (claim.getStatus() != ClaimStatus.DRAFT && !claim.getStatus().isOpen()) {
470	            throw new ClaimReassignException(id, "it is " + claim.getStatus());
471	        }
472	        if (!toOwnAllowed && claim.getPersonId().equals(toPersonId)) {
473	            throw new ClaimReassignException(id, "it is already that person's");
474	        }
475	        periods.requireOpen(sheetId, claim.getDueBy());
476	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
477	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
478	        Person to = people.findByIdAndSheetId(toPersonId, sheetId)
479	                .orElseThrow(() -> new PersonNotFoundException(sheetId, toPersonId));
480	        to.requireClaimable(claim.getDate());
481	        RollupService.Snapshot before = rollup.snapshot(sheetId);
482	        claim.setPersonId(to.getId());
483	        claim.setStated(false, null);
484	        claim.setListed(sheets.nextListed(sheetId));
485	        if (claim.getNumber() != null) {
486	            // A moved claim takes the next number in its sequence; its old one is never used again.
487	            claim.setNumber(nextNumber(sheetId, claim.getDueBy()));
488	        }
489	        Claim saved = claims.saveAndFlush(claim);
490	        audit.recordOnCommit(record("CLAIM_REASSIGNED", user, to, saved) + numberOf(saved.getNumber())
491	                + " from=" + from.getName() + " to=" + to.getName());
492	        rollup.recordChanges(sheetId, user, before);
493	        return saved;
494	    }
495	
496	    /**
497	     * Defer an OPEN claim until a date after the sheet's today: until the sheet's today reaches it the claim counts in
498	     * no total, is not overdue, cannot be settled and is left unbound by a statement. Refused for a claim not OPEN, a
499	     * date not after today, or a closed period.
500	     */
501	    @Transactional
502	    public Claim defer(String sheetId, String user, Long id, LocalDate until) {
503	        Claim claim = claims.findForUpdate(id, sheetId)
504	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
505	        if (claim.getStatus() != ClaimStatus.OPEN) {
506	            throw new ClaimDeferException(id, "it is " + claim.getStatus() + ", only an OPEN claim can be deferred");
507	        }
508	        LocalDate today = sheets.today(sheetId);
509	        if (until == null || !until.isAfter(today)) {
510	            throw new ClaimDeferException(id, "it can only be deferred to a date after " + today);
511	        }
512	        periods.requireOpen(sheetId, claim.getDueBy());
513	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
514	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
515	        RollupService.Snapshot before = rollup.snapshot(sheetId);
516	        claim.setDeferredUntil(until);
517	        Claim saved = claims.saveAndFlush(claim);
518	        audit.recordOnCommit(record("CLAIM_DEFERRED", user, person, saved) + numberOf(saved.getNumber())
519	                + " until=" + until);
520	        rollup.recordChanges(sheetId, user, before);
521	        return saved;
522	    }
523	
524	    /**
525	     * A steward re-settles a SETTLED claim: its due is frozen again at the figure it would have today as an OPEN claim
526	     * bound by no statement (today's rates and grades with its late charge as of today, raised to the floor). Refused for any other
527	     * status, a closed period, or a user not a steward.
528	     */
529	    @Transactional
530	    public Claim resettle(String sheetId, String user, Long id) {
531	        Claim claim = claims.findForUpdate(id, sheetId)
532	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
533	        if (roles.roleOf(sheetId, user) != Role.STEWARD) {
534	            throw new ClaimResettleForbiddenException(id, user);
535	        }
536	        if (claim.getStatus() != ClaimStatus.SETTLED) {
537	            throw new ClaimStatusException(id, claim.getStatus(), ClaimStatus.SETTLED);
538	        }
539	        periods.requireOpen(sheetId, claim.getDueBy());
540	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
541	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
542	        RollupService.Snapshot before = rollup.snapshot(sheetId);
543	        String old = shownDue(sheetId, person, claim);
544	        BigDecimal figure = dueOf(sheetId, person, claim);
545	        Sheet sheet = settings.get(sheetId);
546	        claim.setSettledDue(claim.isCorrection() ? figure
547	                : sheet.floored(sheet.withLateCharge(figure, true, overdueBy(sheet, person, claim), claim.getDate()), claim.getDate()));
548	        Claim saved = claims.saveAndFlush(claim);
549	        log(sheetId, user, person, saved);
550	        audit.recordOnCommit(record("CLAIM_RESETTLED", user, person, saved) + numberOf(saved.getNumber())
551	                + " old=" + old + " new=" + shownDue(sheetId, person, saved));
552	        watches.notifyWatchers(sheetId, user, person, saved.getNumber());
553	        rollup.recordChanges(sheetId, user, before);
554	        return saved;
555	    }
556	
557	    /**
558	     * A steward re-dates an OPEN or PENDING claim. Its due-by stays as it was fixed, and so its period and number, and a
559	     * figure its statement bound it to stays bound. Refused for any other status, a date after its person's retirement,
560	     * a claim due by a date in a closed period, or a user not a steward.
561	     */
562	    @Transactional
563	    public Claim redate(String sheetId, String user, Long id, LocalDate date) {
564	        Claim claim = claims.findForUpdate(id, sheetId)
565	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
566	        if (roles.roleOf(sheetId, user) != Role.STEWARD) {
567	            throw new ClaimRedateForbiddenException(id, user);
568	        }
569	        if (!claim.getStatus().isOpen()) {
570	            throw new ClaimRedateException(id, "it is " + claim.getStatus()
571	                    + ", only an OPEN or PENDING claim can be re-dated");
572	        }
573	        LocalDate old = claim.getDate();
574	        // Its due-by, and so its period, stays as fixed.
575	        periods.requireOpen(sheetId, claim.getDueBy());
576	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
577	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
578	        person.requireClaimable(date);
579	        RollupService.Snapshot before = rollup.snapshot(sheetId);
580	        claim.setDate(date);
581	        if (!claim.isCorrection()) {
582	            claim.setRoundingDate(date);
583	        }
584	        Claim saved = claims.saveAndFlush(claim);
585	        audit.recordOnCommit(record("CLAIM_REDATED", user, person, saved) + numberOf(saved.getNumber())
586	                + " old=" + old + " new=" + date);
587	        rollup.recordChanges(sheetId, user, before);
588	        return saved;
589	    }

