591	    /**
592	     * Split an amount (more than 0.00 and less than its own) off an OPEN claim not deferred. The claim keeps the rest
593	     * and loses any figure a statement bound it to; a new OPEN claim of the same person with the amount split off, the
594	     * same date and note, the next number, opened by the user, due by its date plus the terms in force on that date,
595	     * names the claim's number as the one it was split from. Refused for any other status, a claim due by a date in a
596	     * closed period (the new claim's own due-by is not weighed), or a user
597	     * whose role may not open a claim.
598	     */
599	    @Transactional
600	    public Claim split(String sheetId, String user, Long id, BigDecimal amount) {
601	        Claim claim = claims.findForUpdate(id, sheetId)
602	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
603	        if (!roles.may(sheetId, user, "open")) {
604	            throw new ClaimActionForbiddenException(id, user, "open");
605	        }
606	        if (claim.getStatus() != ClaimStatus.OPEN) {
607	            throw new ClaimSplitException(id, "it is " + claim.getStatus() + ", only an OPEN claim can be split");
608	        }
609	        if (claim.isDeferredOn(sheets.today(sheetId))) {
610	            throw new ClaimSplitException(id, "it is deferred until " + claim.getDeferredUntil());
611	        }
612	        if (amount.signum() <= 0 || amount.compareTo(claim.getAmount()) >= 0) {
613	            throw new ClaimSplitException(id, "the amount split off must be more than 0.00 and less than "
614	                    + claim.getAmount().toPlainString());
615	        }
616	        periods.requireOpen(sheetId, claim.getDueBy());
617	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
618	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
619	        RollupService.Snapshot before = rollup.snapshot(sheetId);
620	        claim.setAmount(claim.getAmount().subtract(amount));
621	        claim.setStated(false, null);
622	        Claim kept = claims.saveAndFlush(claim);
623	        Claim part = new Claim(sheetId, kept.getPersonId(), amount, kept.getDate(), kept.getNote());
624	        part.setRoundingDate(kept.getRoundingDate());
625	        part.setTerms(termsFor(sheetId, person, kept.getDate()));
626	        part.setDueBy(holidays.businessDaysAfter(sheetId, kept.getDate(), part.getTerms()));
627	        part.setListed(sheets.nextListed(sheetId));
628	        part.setLateEntry(periods.softClosedOn(sheetId, part.getDueBy()));
629	        part.setStatus(ClaimStatus.OPEN);
630	        String number = nextNumber(sheetId, part.getDueBy());
631	        part.setNumber(number);
632	        part.setOpenedBy(user);
633	        part.setSplitFrom(kept.getNumber());
634	        part.setTags(kept.getTags());
635	        Claim saved = claims.saveAndFlush(part);
636	        log(sheetId, user, person, saved);
637	        audit.recordOnCommit(record("CLAIM_SPLIT", user, person, kept) + numberOf(kept.getNumber())
638	                + " into=" + number);
639	        audit.recordOnCommit(record("CLAIM_OPENED", user, person, saved) + numberOf(number));
640	        rollup.recordChanges(sheetId, user, before);
641	        return saved;
642	    }
