644	    /**
645	     * Add a proof to a claim, raising its proofs count by one. Refused for a SETTLED or VOID claim, or a closed period.
646	     */
647	    @Transactional
648	    public Claim addProof(String sheetId, String user, Long id) {
649	        Claim claim = claims.findForUpdate(id, sheetId)
650	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
651	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
652	            throw new ClaimProofException(id, "it is " + claim.getStatus() + ", a proof cannot be added");
653	        }
654	        periods.requireOpen(sheetId, claim.getDueBy());
655	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
656	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
657	        claim.addProof();
658	        Claim saved = claims.saveAndFlush(claim);
659	        audit.recordOnCommit(record("CLAIM_PROOF_ADDED", user, person, saved) + numberOf(saved.getNumber())
660	                + " proofs=" + saved.getProofs());
661	        return saved;
