664	    /**
665	     * Remind an OPEN or PENDING claim: REMIND is written and the claim's reminded date becomes the sheet's today.
666	     * Refused for any other status, and for a claim already reminded on the sheet's today.
667	     */
668	    @Transactional
669	    public Claim remind(String sheetId, String user, Long id) {
670	        Claim claim = claims.findForUpdate(id, sheetId)
671	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
672	        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
673	            throw new ClaimRemindException(id, "it is " + claim.getStatus()
674	                    + ", only an OPEN or PENDING claim can be reminded");
675	        }
676	        LocalDate today = sheets.today(sheetId);
677	        if (today.equals(claim.getRemindedOn())) {
678	            throw new ClaimRemindException(id, "it was already reminded on " + today);
679	        }
680	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
681	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
682	        claim.setRemindedOn(today);
683	        Claim saved = claims.saveAndFlush(claim);
684	        audit.recordOnCommit(record("REMIND", user, person, saved) + numberOf(saved.getNumber()));
685	        return saved;
686	    }
