688	    /**
689	     * A claim whose due (as the clerk limit weighs it) is above the proof threshold in force on its date (its person's
690	     * grade's own then, else the sheet's) cannot be settled or approved while it has no proof; refused then. A due of
691	     * n/a is within any threshold.
692	     */
693	    private void requireProof(String sheetId, Person person, Claim claim) {
694	        BigDecimal threshold = settings.get(sheetId).proofThresholdFor(person.gradeOn(claim.getDate()), claim.getDate());
695	        if (threshold == null || claim.getProofs() > 0) {
696	            return;
697	        }
698	        BigDecimal due = liveDue(sheetId, person, claim, figureOf(sheetId, person, claim));
699	        if (due != null && due.compareTo(threshold) > 0) {
700	            throw new ClaimProofException(claim.getId(), "its due " + due.toPlainString()
701	                    + " is above the proof threshold " + threshold.toPlainString() + " and it has no proof");
702	        }
703	    }
704	
705	    /**
706	     * A claim whose due is above the note threshold in force on its date cannot be opened while its note is empty;
707	     * refused then. A due of n/a is within any threshold.
708	     */
709	    private void requireNote(String sheetId, Person person, Claim claim) {
710	        BigDecimal threshold = settings.get(sheetId).noteThresholdOn(claim.getDate());
711	        if (threshold == null || !noteOf(claim.getNote()).isEmpty()) {
712	            return;
713	        }
714	        BigDecimal due = liveDue(sheetId, person, claim, figureOf(sheetId, person, claim));
715	        if (due != null && due.compareTo(threshold) > 0) {
716	            throw new ClaimNoteException(claim.getId(), "its due " + due.toPlainString()
717	                    + " is above the note threshold " + threshold.toPlainString() + " and its note is empty");
718	        }
719	    }
720	
721	    /**
722	     * Only a steward voids a SETTLED claim, and only within the days allowed after its settlement (the date of the last
723	     * SETTLED line of its status log) by the sheet's today; refused otherwise.
724	     */
725	    private void requireSettledVoidable(String sheetId, String user, Claim claim) {
726	        if (roles.roleOf(sheetId, user) != Role.STEWARD) {
727	            throw new ClaimActionForbiddenException(claim.getId(), user, "void a settled claim");
728	        }
729	        LocalDate settledOn = logOf(claim).stream()
730	                .filter(l -> l.getStatus() == ClaimStatus.SETTLED)
731	                .map(ClaimLog::getDate)
732	                .reduce((first, last) -> last)
733	                .orElse(null);
734	        LocalDate today = sheets.today(sheetId);
735	        if (settledOn == null || today.isAfter(settledOn.plusDays(SETTLED_VOID_DAYS))) {
736	            throw new ClaimVoidException(claim.getId(), "a settled claim can only be voided within "
737	                    + SETTLED_VOID_DAYS + " days of its settlement on " + settledOn);
738	        }
739	    }
740	
741	    /** The PENDING claim a steward decides; refused for any other status, a closed period, or a user not a steward. */
742	    private Claim pendingForDecision(String sheetId, String user, Long id, ClaimStatus to) {
743	        Claim claim = claims.findForUpdate(id, sheetId)
744	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
745	        if (claim.getStatus() != ClaimStatus.PENDING) {
746	            throw new ClaimStatusException(id, claim.getStatus(), to);
747	        }
748	        periods.requireOpen(sheetId, claim.getDueBy());
749	        if (roles.roleOf(sheetId, user) != Role.STEWARD) {
750	            throw new ClaimApprovalForbiddenException(id, user, "only a steward approves or rejects a pending claim");
751	        }
752	        return claim;
753	    }
754	
755	    /**
756	     * Fixes the due the claim shows as it settles: its figure (the one its statement binds it to, else worked out from
757	     * the rate on the claim's date) with its late charge, raised to the floor on its date, frozen in (a correction
758	     * freezes its bare figure); with no figure it stays live. Gives the due at the
759	     * end of its audit record.
760	     */
761	    private String settle(String sheetId, Person person, Claim claim) {
762	        BigDecimal figure = figureOf(sheetId, person, claim);
763	        Sheet sheet = settings.get(sheetId);
764	        BigDecimal settledDue = figure == null || claim.isCorrection() ? figure
765	                : sheet.floored(figure.add(sheet.lateCharge(figure, overdueBy(sheet, person, claim), claim.getDate())), claim.getDate());
766	        claim.setSettledDue(settledDue);
767	        return " due=" + (settledDue == null ? "n/a" : settledDue.toPlainString());
768	    }
769	
770	    /** Logs the claim's status now: who changed it, the sheet's today, and its due as computed at this moment. */
771	    private void log(String sheetId, String user, Person person, Claim claim) {
772	        logs.save(new ClaimLog(sheetId, claim.getId(), claim.getStatus(), user, sheets.today(sheetId),
773	                shownDue(sheetId, person, claim)));
774	    }
775	
776	    /**
777	     * The claim's due as shown: the one fixed when it was settled, else its live due; two decimals, or n/a.
778	     */
779	    private String shownDue(String sheetId, Person person, Claim claim) {
780	        BigDecimal due = claim.getSettledDue() != null ? claim.getSettledDue()
781	                : liveDue(sheetId, person, claim, figureOf(sheetId, person, claim));
782	        return due == null ? "n/a" : due.setScale(2, RoundingMode.HALF_EVEN).toPlainString();
783	    }
784	
785	    /** The figure under the claim's due: the one its statement binds it to now, else worked out from the rate. */
786	    private BigDecimal figureOf(String sheetId, Person person, Claim claim) {
787	        return claim.isBound() ? claim.getStatedDue() : dueOf(sheetId, person, claim);
788	    }
789	
790	    /**
791	     * A negative amount (a correction) must name, by number, a SETTLED claim of the same person; any other amount
792	     * names none. Refused otherwise. Gives the date of the claim a correction corrects (it rounds by that date), null
793	     * for any other claim.
794	     */
795	    private LocalDate requireCorrection(String sheetId, Long personId, BigDecimal amount, String corrects) {
796	        if (amount.signum() >= 0) {
797	            if (corrects != null) {
798	                throw new ClaimCorrectionException("Only a correction (a negative amount) corrects a claim");
799	            }
800	            return null;
801	        }
802	        if (corrects == null) {
803	            throw new ClaimCorrectionException("A negative amount must name the settled claim it corrects");
804	        }
805	        return claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
806	                .filter(c -> c.getStatus() == ClaimStatus.SETTLED)
807	                .map(Claim::getDate)
808	                .orElseThrow(() -> new ClaimCorrectionException(
809	                        "Claim " + corrects + " is not a settled claim of the same person"));
810	    }
811	
812	    /**
813	     * The claim's amount at the rate its person's grade has on its date, two decimals rounded as the sheet's policy
814	     * date has the claim round (the rate figure, with no floor); null (n/a) with no rate.
815	     */
816	    private BigDecimal dueOf(String sheetId, Person person, Claim claim) {
817	        Sheet sheet = settings.get(sheetId);
818	        return rates.rateOn(sheetId, person.gradeOn(claim.getDate()), claim.getDate())
819	                .map(Rate::getPct)
820	                .map(pct -> sheet.rateStep(claim.getAmount(), pct, claim.getRoundingDate()))
821	                .orElse(null);
822	    }
823	
824	    /**
825	     * The live due on a figure: the greater of the floor in force on the claim's date and the figure with the late
826	     * charge of an OPEN or PENDING claim overdue on the sheet's today added on top (no late charge on a claim deferred
827	     * on the sheet's today; a correction has neither floor nor late charge); null (n/a) stays null.
828	     */
829	    private BigDecimal liveDue(String sheetId, Person person, Claim claim, BigDecimal figure) {
830	        Sheet sheet = settings.get(sheetId);
831	        if (claim.isCorrection()) {
832	            return figure;
833	        }
834	        return sheet.floored(sheet.withLateCharge(figure, claim.getStatus().isOpen()
835	                && !claim.isDeferredOn(sheet.getToday()), overdueBy(sheet, person, claim), claim.getDate()), claim.getDate());
836	    }
837	
838	    /** The day the claim goes overdue after: its due-by plus the grace days its person's grade has on its date. */
839	    private static LocalDate overdueBy(Sheet sheet, Person person, Claim claim) {
840	        return sheet.overdueBy(claim.getDueBy(), person.gradeOn(claim.getDate()), claim.getDate());
841	    }
842	
843	    /** The amount as shown (two decimals) and the date as yyyy-mm-dd. */
844	    private static String record(String event, String user, Person person, Claim claim) {
845	        return event + " sheet=" + claim.getSheetId() + " by=" + user + " person=" + person.getName()
846	                + " amount=" + claim.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString()
847	                + " date=" + claim.getDate();
848	    }
849	
850	    /** The claim's number at the end of an audit record, or nothing when it has none. */
851	    private static String numberOf(String number) {
852	        return number == null ? "" : " number=" + number;
853	    }
854	
855	    /**
856	     * The number a claim due by the date gets when opened: while the sheet numbers by period, the next in its
857	     * period's own sequence (X for no period); otherwise the next sheet-wide number.
858	     */
859	    public String nextNumber(String sheetId, LocalDate date) {
860	        if (settings.get(sheetId).numbersByPeriod()) {
861	            return sheets.nextSequenceNumber(sheetId, periods.nameOn(sheetId, date).orElse("X"));
862	        }
863	        return String.valueOf(sheets.nextClaimNumber(sheetId));
864	    }
865	
866	    /** The terms of the person on the date: their own, else their grade's on that date, else the sheet's then. */
867	
868	    private int termsFor(String sheetId, Person person, LocalDate date) {
869	        return person.getTerms() != null ? person.getTerms()
870	                : settings.termsFor(sheetId, person.gradeOn(date), date);
871	    }
872	
873	    private LocalDate dateOr(String sheetId, LocalDate date) {
874	        return date != null ? date : sheets.today(sheetId);
875	    }
876	
877	    private static String noteOf(String note) {
878	        return note == null ? "" : note.trim();
879	    }
880	
881	    /** The reference with surrounding spaces removed; null for a blank one (no reference). */
882	    /**
883	     * The tags of comma separated text, each trimmed and lower-cased, without repeats, sorted and joined by commas
884	     * (null when there are none), each noted as used on the sheet.
885	     */
886	    private String tagged(String sheetId, String text) {
887	        if (text == null) {
888	            return null;
889	        }
890	        List<String> list = Arrays.stream(text.split(",")).map(t -> t.trim().toLowerCase(Locale.ROOT))
891	                .filter(t -> !t.isEmpty()).distinct().sorted().toList();
892	        for (String tag : list) {
893	            if (!tags.existsBySheetIdAndTag(sheetId, tag)) {
894	                tags.save(new SheetTag(sheetId, tag));
895	            }
896	        }
897	        return list.isEmpty() ? null : String.join(",", list);
898	    }
899	
900	    private static String refOf(String ref) {
901	        return ref == null || ref.isBlank() ? null : ref.trim();
902	    }
903	}
